<?php require_once '../includes/config.php'; if(!empty($_SESSION['admin_id']))redirect('dashboard.php');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';$s=$conn->prepare('SELECT id,name,username,password FROM admin WHERE username=?');$s->bind_param('s',$u);$s->execute();$a=$s->get_result()->fetch_assoc();if($a&&password_verify($p,$a['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];$_SESSION['admin_username']=$a['username'];redirect('dashboard.php');}$error='Incorrect username or password.';}$title='Admin Login';require '../includes/header.php';?><div class="page"><section class="login-card"><div class="login-head"><h1>Admin portal</h1><p>Manage complaints and escalations.</p></div><div class="login-body"><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="post"><div class="field"><label>Username</label><input name="username" required autofocus></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn btn-primary" style="width:100%">Sign in</button></form><p class="muted"><a href="../login.php">Back to user login</a></p></div></section></div><?php require '../includes/footer.php';?>
